cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Get user's flight bookings
console.log('=== USER BOOKINGS ===');
const bookings = db.prepare(\"SELECT * FROM flight_bookings WHERE user_id = 'user_59b22691'\").all();
bookings.forEach(b => console.log(JSON.stringify(b, null, 2)));

// Search for JFK to LHR flights
console.log('\n=== JFK → LHR FLIGHTS ===');
const jfkLhr = db.prepare(\"SELECT * FROM flights WHERE origin = 'JFK' AND destination = 'LHR'\").all();
if (jfkLhr.length === 0) {
  console.log('No direct JFK→LHR flights found.');
  // Check if LHR exists at all
  const lhrFlights = db.prepare(\"SELECT DISTINCT origin, destination FROM flights WHERE origin = 'LHR' OR destination = 'LHR'\").all();
  console.log('Any flights involving LHR:', lhrFlights);
  // Check all JFK routes
  const jfkFlights = db.prepare(\"SELECT DISTINCT origin, destination FROM flights WHERE origin = 'JFK'\").all();
  console.log('All routes from JFK:', jfkFlights);
} else {
  jfkLhr.forEach(f => console.log(JSON.stringify(f, null, 2)));
}
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Current flight
const current = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FL658038'\").get();
const currentPrices = JSON.parse(current.cabin_prices_json);

// New flight
const newFlight = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FLABBF26'\").get();
const newPrices = JSON.parse(newFlight.cabin_prices_json);
const newDates = JSON.parse(newFlight.dates_json);

console.log('=== CURRENT FLIGHT (FL658038) ===');
