cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Get current booking
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
const oldFlightId = booking.flight_id;
const oldPrice = booking.price_paid;

// Get new flight details
const newFlight = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FLABBF26'\").get();
const newPrices = JSON.parse(newFlight.cabin_prices_json);
const newBusinessPrice = newPrices.business;

// Price difference
const priceDiff = newBusinessPrice - oldPrice;

// Update the booking
const stmt = db.prepare(\`
  UPDATE flight_bookings 
  SET flight_id = 'FLABBF26',
      price_paid = ?,
      fare_difference = ?,
      flights_json = ?
  WHERE booking_id = 'BK-B70889'
\`);

const newFlightsJson = JSON.stringify([{flight_number: 'FLABBF26', date: '2026-09-10'}]);
const result = stmt.run(newBusinessPrice, priceDiff, newFlightsJson);

console.log('Rows updated:', result.changes);

// Verify the update
const updated = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
console.log('\\n=== UPDATED BOOKING ===');
console.log('Booking ID:', updated.booking_id);
console.log('Flight ID:', updated.flight_id);
console.log('Price Paid:', updated.price_paid);
console.log('Fare Difference:', updated.fare_difference);
console.log('Cabin:', updated.cabin_class);
console.log('Status:', updated.status);
console.log('Flights JSON:', updated.flights_json);
console.log('Payment Method:', updated.payment_method);

db.close();
"
